{
    const unsigned char *p1 = ptr1, *p2 = ptr2;
    size_t align;
    int result;

    if (n < sizeof(uint64_t))
        return memcmp_bytes(p1, p2, n);

    align = -(size_t)p1 & (sizeof(uint64_t) - 1);

    if ((result = memcmp_bytes(p1, p2, align)))
        return result;

    p1 += align;
    p2 += align;
    n  -= align;

    return memcmp_blocks(p1, p2, n);
}

