    status = NtDeviceIoControlFile( (HANDLE)s, NULL, NULL, NULL, &io, IOCTL_AFD_GETSOCKNAME, NULL, 0, addr, *len );
    if (!status)
        *len = io.Information;
    WSASetLastError( NtStatusToWSAError( status ) );
    TRACE( "status %#lx.\n", status );
    return status ? -1 : 0;
}

{
    unsigned long a[4] = { 0 };
    const char *s = str;
    unsigned char *d;
    unsigned int i;
    u_long addr;
    char *z;

    TRACE( "str %s.\n", debugstr_a(str) );

    if (!s)
    {
        SetLastError( WSAEFAULT );
        return INADDR_NONE;
    }

    d = (unsigned char *)&addr;

    if (s[0] == ' ' && !s[1]) return 0;

    for (i = 0; i < 4; ++i)
    {
        a[i] = strtoul( s, &z, 0 );
        if (z == s || !isdigit( *s )) return INADDR_NONE;
        if (!*z || isspace(*z)) break;
        if (*z != '.') return INADDR_NONE;
        s = z + 1;
    }

    if (i == 4) return INADDR_NONE;

    switch (i)
    {
        case 0:
            a[1] = a[0] & 0xffffff;
            a[0] >>= 24;
            /* fallthrough */
        case 1:
            a[2] = a[1] & 0xffff;
            a[1] >>= 16;
            /* fallthrough */
        case 2:
            a[3] = a[2] & 0xff;
            a[2] >>= 8;
    }
    for (i = 0; i < 4; ++i)
    {
        if (a[i] > 255) return INADDR_NONE;
        d[i] = a[i];
    }
    return addr;
}

